import json
import re
from html import unescape
from pathlib import Path


sources = json.loads(Path('source.json').read_text())


def paragraphs(xml):
    return re.findall(r'<p>(.*?)</p>', xml, re.S)


def plain(xml):
    return unescape(re.sub(r'<[^>]*>', '', xml))


def xml(ps):
    return '\n'.join('<p>' + p + '</p>' for p in ps)


def effect(kind, measure_id, description, before, after, unit,
           affected_population, conditions_and_transition,
           replacement_or_new_burdens, source_quote, proposed_quote):
    return dict(kind=kind, measure_id=measure_id, description=description,
                before=before, after=after, unit=unit,
                affected_population=affected_population,
                conditions_and_transition=conditions_and_transition,
                replacement_or_new_burdens=replacement_or_new_burdens,
                source_quote=source_quote, proposed_quote=proposed_quote)


a = sources[0]
p = paragraphs(a['source_xml'])
assert len(p) == 14
q = p.copy()
q[1] = q[1].replace('D. 331-14 à R. 331-16', 'D. 331-14 à D. 331-16')
q[5] = "Le bénéfice de cette durée d'exonération n'est subordonné ni à la délivrance d'un certificat spécifique par l'administration chargée de l'équipement ni à sa jonction à la déclaration prévue par l'article 1406. Le respect des critères est apprécié au moyen des données et pièces légalement disponibles, notamment des études et attestations déjà établies pour la construction. Aucun certificat, certification de produit ou attestation supplémentaire n'est exigé pour le seul bénéfice de cette exonération. L'administration ne peut demander une nouvelle communication des pièces exactes et à jour dont elle dispose légalement. Ses pouvoirs de contrôle s'exercent dans les conditions prévues par le livre des procédures fiscales."
q[6] = "La définition technique de ces critères est fixée par décret en Conseil d'Etat, sans rétablir le certificat, la certification de produit ou l'attestation supplémentaire écartés au précédent alinéa."
q[11] = "Cette prolongation s'applique de plein droit aux logements qui remplissent ces conditions. Son bénéfice n'est subordonné ni à l'établissement ni à la transmission d'une liste annuelle des logements et de leurs propriétaires par la commission mentionnée à l'article L. 615-1 du code de la construction et de l'habitation. L'administration utilise les décisions et les données légalement disponibles relatives aux mesures de sauvegarde ; aucune liste ou déclaration annuelle de remplacement n'est exigée."
agreement = "d'une convention et d'une décision d'agrément prise par le représentant de l'Etat dans le département"
assert agreement in q[12] and agreement in q[13]
q[12] = q[12].replace(agreement, "d'une convention avec l'Etat")
local_vote = "IV. - Sur délibération des communes et des établissements publics de coopération intercommunale à fiscalité propre, prise dans les conditions prévues à l'article 1639 A bis, les logements"
assert q[13].startswith(local_vote)
q[13] = q[13].replace(local_vote, 'IV. - Les logements', 1).replace(agreement, "d'une convention avec l'Etat")
